<?php
namespace ZinCelestial\Platform\OperationsCenter;defined('ABSPATH')||exit;
final class OperationsCenterService {public function __construct(private \wpdb $db,private string $runs,private int $site_id){}public function summary():array{$rows=$this->db->get_results($this->db->prepare("SELECT JSON_UNQUOTE(JSON_EXTRACT(payload,'$.status')) status,COUNT(*) total FROM {$this->runs} WHERE site_id=%d GROUP BY status",$this->site_id),ARRAY_A);$counts=[];foreach((array)$rows as $r)$counts[sanitize_key($r['status'])]=(int)$r['total'];return ['site_id'=>$this->site_id,'workflows'=>$counts,'attention'=>($counts['failed']??0)+($counts['pending_approval']??0),'generated_at'=>time()];}public function recent(int $limit=25):array{$limit=max(1,min(100,$limit));return (array)$this->db->get_results($this->db->prepare("SELECT run_id,payload,version,updated_at FROM {$this->runs} WHERE site_id=%d ORDER BY updated_at DESC LIMIT %d",$this->site_id,$limit),ARRAY_A);}}
